def find_mst_paths(points):
    """Find MST of points using Prim's algorithm, track paths taken"""
    n = len(points)
    in_tree = [False] * n
    min_edge = [0] * n
    parent = [None] * n
    in_tree[0] = True
    min_edge[0] = -1

    for _ in range(n - 1):
        # Find minimum edge to unvisited node
        min_dist = float('inf')
        best_edge_to = None
        best_from = None

        for i in range(n):
            if in_tree[i]:
                for j in range(n):
                    if not in_tree[j]:
                        dist = manhattan_distance(points[i], points[j])
                        if dist < min_dist:
                            min_dist = dist
                            best_edge_to = j
                            best_from = i

        if best_edge_to is None:
            break

        in_tree[best_edge_to] = True
        parent[best_edge_to] = best_from
        min_edge[best_edge_to] = min_dist

    return parent

